(()=>{
 const dialog=document.querySelector('#quick-payment-dialog'),form=document.querySelector('#quick-payment-form'),feedback=document.querySelector('#quick-payment-status'),balance=document.querySelector('#quick-current-balance');
 let busy=false,students=[],adminId=null,draft=null,balanceVersion=0;
 const money=value=>(value/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';
 async function api(path,data){const response=await fetch('/api/'+path,{cache:'no-store',...(data?{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось выполнить запрос. Проверьте данные.');return result}
 function mode(calculate=false){const packageMode=form.elements.mode.value==='package';document.querySelector('#quick-package').hidden=!packageMode;form.elements.lesson_count.required=packageMode;form.elements.lesson_count.disabled=busy||!packageMode;if(calculate&&packageMode){const rate=students.find(s=>s.id===Number(form.elements.student_id.value))?.default_price_kopecks||0,count=Number(form.elements.lesson_count.value);if(rate>0&&Number.isInteger(count)&&count>0)form.elements.amount.value=(count*rate/100).toFixed(2)}}
 function freeze(value){busy=value;form.querySelectorAll('input,select,button').forEach(e=>e.disabled=value);mode()}
 async function showBalance(){const version=++balanceVersion;balance.textContent='Загружаем баланс…';try{const result=await api('finance/balance?student_id='+form.elements.student_id.value+'&limit=1');if(version===balanceVersion)balance.textContent='Текущий баланс: '+money(result.student.balance_kopecks)}catch(e){if(version===balanceVersion)balance.textContent='Не удалось обновить баланс.'}}
 window.openAdminPayment=async(studentId)=>{if(busy||dialog.open)return;form.reset();feedback.textContent='Загружаем учеников…';balance.textContent='';form.elements.student_id.replaceChildren();dialog.showModal();freeze(true);try{const user=await api('auth/me');if(user.role!=='admin'||user.must_change_password)throw Error('Для внесения оплаты войдите как администратор.');adminId=user.id;students=[];let offset=0,total;do{const page=await api('admin/students?limit=100&offset='+offset+'&sort=name');students.push(...page.items);total=page.total;offset+=100}while(offset<total);for(const s of students){const option=document.createElement('option');option.value=s.id;option.textContent=s.name+' ('+s.username+')'+(s.is_active?'':' · В архиве');form.elements.student_id.append(option)}if(studentId)form.elements.student_id.value=String(studentId);if(!form.elements.student_id.value)throw Error('Сначала добавьте ученика.');feedback.textContent='';await showBalance();form.elements.amount.focus()}catch(e){feedback.textContent=e.message}finally{freeze(false);form.elements.amount.focus()}};
 document.querySelectorAll('[data-open-payment]').forEach(button=>button.onclick=()=>window.openAdminPayment());
 document.querySelector('#quick-payment-close').onclick=()=>{if(!busy)dialog.close()};dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault()});
 form.elements.mode.onchange=()=>mode(true);form.elements.lesson_count.oninput=()=>mode(true);form.elements.student_id.onchange=()=>{feedback.textContent='';mode(true);void showBalance()};
 form.onsubmit=async event=>{event.preventDefault();if(busy||!adminId)return;const amount=form.elements.amount.value.trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(amount)){feedback.textContent='Укажите сумму с точностью до копеек.';return}const [rub,kop='']=amount.split('.'),payload={student_id:Number(form.elements.student_id.value),amount_kopecks:Number(rub)*100+Number(kop.padEnd(2,'0')),lesson_count:form.elements.mode.value==='package'?Number(form.elements.lesson_count.value):null,note:form.elements.note.value.trim()};if(!Number.isSafeInteger(payload.amount_kopecks)||payload.amount_kopecks<1||payload.amount_kopecks>100000000){feedback.textContent='Сумма должна быть от 0,01 до 1 000 000 ₽.';return}const signature=JSON.stringify(payload),key='krug-pi-payment-retry:'+adminId;try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved?.signature===signature)draft=saved}catch{}if(draft?.signature!==signature)draft={signature,id:crypto.randomUUID()};try{sessionStorage.setItem(key,JSON.stringify(draft))}catch{}freeze(true);feedback.textContent='Сохраняем…';try{await api('finance/payments',{...payload,request_id:draft.id});draft=null;try{sessionStorage.removeItem(key)}catch{}form.elements.amount.value='';form.elements.note.value='';form.elements.lesson_count.value='';feedback.textContent='Оплата зачислена: '+money(payload.amount_kopecks)+'.';await showBalance();window.dispatchEvent(new Event('admin-payment-saved'))}catch(e){feedback.textContent=e.message}finally{freeze(false)}};
})();
